import React, { useState } from 'react';
import FilmsGallery from '../components/FilmsGallery';
import Filters from '../components/Filters';

// Ваші дані тепер живуть тут (або імпортуйте їх з окремого файлу)
const initialFilms = [
    { id: 1, name: 'Taylor Swift: The Eras Tour', time: 169, IMDb_rating: 8.0, price: 300, image: 'films_photo/Taylor Swift_ The Eras Tour (2023).jpg' },
    { id: 2, name: 'All Too Well', time: 15, IMDb_rating: 8.4, price: 150, image: 'films_photo/All Too Well (2021).jpg' },
    { id: 3, name: 'Miss Americana', time: 85, IMDb_rating: 7.4, price: 200, image: 'films_photo/Miss Americana (2020).jpg' },
    { id: 4, name: 'Reputation Stadium Tour', time: 125, IMDb_rating: 8.4, price: 250, image: 'films_photo/Taylor Swift_ Reputation Stadium Tour (2018).jpg' }
];

const Catalog = () => {
    // Стан для обраного сортування
    const [sortOption, setSortOption] = useState('default');

    // Логіка сортування
    const getSortedFilms = () => {
        // Робимо копію масиву, щоб не мутувати оригінал
        const sorted = [...initialFilms];

        if (sortOption === 'price_asc') {
            return sorted.sort((a, b) => a.price - b.price);
        } else if (sortOption === 'price_desc') {
            return sorted.sort((a, b) => b.price - a.price);
        } else if (sortOption === 'rating') {
            return sorted.sort((a, b) => b.IMDb_rating - a.IMDb_rating);
        }
        
        return sorted;
    };

    return (
        <div className="container">
            <h1>Full Catalog</h1>
            <div className="catalog-container">
                {/* Передаємо функцію зміни сортування в Filters */}
                <Filters setSort={setSortOption} />
                
                <div style={{ flexGrow: 1 }}>
                    {/* Передаємо вже ВІДСОРТОВАНІ фільми в галерею */}
                    <FilmsGallery films={getSortedFilms()} />
                </div>
            </div>
        </div>
    );
}

export default Catalog;
